/* Zen mode: quiet the manuscript down to plain text while writing.
   The marks (and their data) are untouched — only the visual
   highlighting is suppressed, so nothing is lost on toggle-off.
   The toolbar and all marks fade out, reappearing on hover so the
   writer can still reach tools. */
.twyne-editor.zen-mode .twyne-persona-note {
  background: none;
  border-bottom: none;
  cursor: text;
}
.twyne-editor.zen-mode .ProseMirror .twyne-comment-mark {
  background: none !important;
  border-bottom: none !important;
  cursor: text;
}
.twyne-editor.zen-mode .ProseMirror .citation-mark {
  background: none;
  border-bottom: none;
  cursor: text;
}
.twyne-editor.zen-mode .twyne-endnote {
  color: var(--color-ink-muted);
  background: none;
}
/* Fade out the toolbar in zen mode. It reappears on hover so tools
   remain reachable. */
.twyne-editor.zen-mode .twyne-toolbar {
  opacity: 0.15;
  transition: opacity 0.3s ease;
}
.twyne-editor.zen-mode .twyne-toolbar:hover {
  opacity: 1;
}
.persona-note-thread {
  max-height: 240px;
  overflow-y: auto;
}

import { Mark, type Editor } from "@tiptap/core";

export interface CommentMarkOptions {
  HTMLAttributes: Record<string, any>;
}

export interface CommentMarkAttributes {
  id: string;
  author?: string;
  color?: string;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    commentMark: {
      setComment: (attrs: CommentMarkAttributes) => ReturnType;
      unsetComment: () => ReturnType;
    };
  }
}

export const CommentMark = Mark.create<CommentMarkOptions>({
  name: "commentMark",

  // Margin threads are independent even when they quote the same passage.
  // Allow multiple comment marks to coexist instead of letting the newest one
  // replace the first at an identical selection.
  excludes: "",

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  addAttributes() {
    return {
      id: {
        default: null,
        parseHTML: (element) => element.getAttribute("data-comment-id"),
        renderHTML: (attributes) => {
          if (!attributes.id) return {};
          return { "data-comment-id": attributes.id };
        },
      },
      author: {
        default: "You",
        parseHTML: (element) => element.getAttribute("data-comment-author"),
        renderHTML: (attributes) => {
          if (!attributes.author) return {};
          return { "data-comment-author": attributes.author };
        },
      },
      color: {
        default: "var(--color-writer-note)",
        parseHTML: (element) => {
          const color = element.getAttribute("data-comment-color");
          // Migrate comments saved before writer notes received their own
          // semantic color. Mustard belongs to M. Le Stylo.
          return !color || color === "var(--color-mustard)"
            ? "var(--color-writer-note)"
            : color;
        },
        renderHTML: (attributes) => {
          if (!attributes.color) return {};
          return { "data-comment-color": attributes.color };
        },
      },
    };
  },

  parseHTML() {
    return [
      {
        tag: "span[data-comment-id]",
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    const color =
      HTMLAttributes["data-comment-color"] ?? "var(--color-writer-note)";
    return [
      "span",
      {
        ...this.options.HTMLAttributes,
        ...HTMLAttributes,
        class: "twyne-comment-mark",
        style: `background: color-mix(in srgb, ${color} 18%, transparent); border-bottom: 2px solid ${color}; cursor: text;`,
      },
      0,
    ];
  },

  addCommands() {
    return {
      setComment:
        (attrs) =>
        ({ chain }) => {
          return chain()
            .setMark("commentMark", {
              id: attrs.id,
              author: attrs.author ?? "You",
              color: attrs.color ?? "var(--color-writer-note)",
            })
            .run();
        },
      unsetComment:
        () =>
        ({ chain }) => {
          return chain().unsetMark("commentMark").run();
        },
    };
  },
});

/** Remove one comment id without disturbing another mark on the same quote. */
export function removeCommentMarkById(
  editor: Editor,
  commentId: string,
): boolean {
  const { state, view } = editor;
  const type = state.schema.marks.commentMark;
  if (!type) return false;

  const tr = state.tr;
  state.doc.descendants((node, pos) => {
    if (!node.isText) return true;
    for (const mark of node.marks) {
      if (mark.type === type && mark.attrs.id === commentId) {
        tr.removeMark(pos, pos + node.nodeSize, mark);
      }
    }
    return true;
  });
  if (!tr.docChanged) return false;
  view.dispatch(tr);
  return true;
}

  cleanup(() =>
    window.removeEventListener(OPEN_WRITER_COMMENT_EVENT, onOpen),
  );
});

const closeUserCommentPopover = $(() => {
  threadRequest.value++;
  const popover = store.userCommentPopover;
  store.userCommentPopover =
    popover?.mode === "compose" ? { ...popover, visible: false } : null;
});

const submitUserCommentReply = $(async (commentId: string) => {
  const popover = store.userCommentPopover;
  if (!popover || popover.id !== commentId) return;
  const text = popover.draft.trim();
  if (!text) return;
  const reply: UserCommentReply = {
    id: `ucr-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    author: "You",
    authorKind: "user",
    text,
    createdAt: Date.now(),
  };
  // Local persistence
  const all = await appendUserCommentReply(commentId, reply);
  const updated = all.find((x) => x.id === commentId);
  if (updated) {
    const savedDraft = threadDrafts[commentItemId(commentId)]?.trim();
    if (savedDraft === text) threadDrafts[commentItemId(commentId)] = "";
    if (store.userCommentPopover?.id === commentId)
      store.userCommentPopover = {
        ...store.userCommentPopover,
        replies: updated.replies,
        draft: threadDrafts[commentItemId(commentId)] ?? "",
      };
  }
  // Local replies sync only when there is an authenticated identity.
  const client = clientSig.value;
  if (client && hasAuthenticatedConvexIdentity(auth.value)) {
    try {
      await client.mutation(api.userComments.addReply, {
        replyId: reply.id,
        commentId,
        author: reply.author,
        text: reply.text,
      });
    } catch (err) {
      reportCommentSyncError("add-comment-reply", err);
    }
  }
  // Tell the Marginalia panel (and any other listener) the thread grew.
  // Without this, the right-rail view stays stale until the panel
  // remounts, which makes it look like the reply vanished.
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
  window.dispatchEvent(
    new CustomEvent("twyne:user-comment-mentions", {
      detail: { commentId, text },
    }),
  );
});

const toggleResolveUserComment = $(async (commentId: string) => {
  const all = await toggleUserCommentResolved(commentId);
  const updated = all.find((x) => x.id === commentId);
  const popover = store.userCommentPopover;
  if (popover && popover.id === commentId && updated) {
    store.userCommentPopover = { ...popover, resolved: updated.resolved };
  }
  const client = clientSig.value;
  if (client && updated && hasAuthenticatedConvexIdentity(auth.value)) {
    try {
      await client.mutation(api.userComments.setCommentResolved, {
        commentId,
        resolved: updated.resolved,
      });
    } catch (err) {
      reportCommentSyncError("resolve-comment", err);
    }
  }
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
});

const deleteUserCommentLocal = $(async (commentId: string) => {
  await deleteUserComment(commentId);
  // Strike exactly this mark from the document. A second margin may quote
  // the same passage and must remain visible.
  if (store.editor) removeCommentMarkById(store.editor, commentId);
  if (store.userCommentPopover?.id === commentId) {
    store.userCommentPopover = null;
  }
  const client = clientSig.value;
  if (client && hasAuthenticatedConvexIdentity(auth.value)) {
    try {
      await client.mutation(api.userComments.deleteComment, { commentId });
    } catch (err) {
      reportCommentSyncError("delete-comment", err);
    }
  }
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
});

