// Qwik must capture these QRLs before the editor setup task is extracted.
/**
 * Open the user-comment popover for a given mark. Loads the body,
 * replies, and resolve state from Lix (Convex will catch up on
 * the next sync). The popover position is anchored to the mark's
 * bounding rect, with a small offset to keep it readable.
 */
const openUserCommentPopover = $(
  async (commentId: string, markEl: HTMLElement) => {
    const token = ++threadRequest.value;
    const rect = markEl.getBoundingClientRect();
    const pageRect = markEl
      .closest<HTMLElement>(".page-canvas")
      ?.getBoundingClientRect();
    const geom = computeMarginCardGeometry({
      vw: window.innerWidth,
      vh: window.innerHeight,
      rect: {
        left: rect.left,
        top: rect.top,
        bottom: rect.bottom,
      },
      page: pageRect
        ? { left: pageRect.left, right: pageRect.right }
        : { left: rect.left, right: rect.right },
    });
    const itemId = commentItemId(commentId);
    const slot = await marginSurface()?.reveal(itemId, rect.top);
    const place = slot
      ? { ...slotPlacement(slot), margin: itemId }
      : { x: geom.x, top: geom.top, bottom: geom.bottom, maxH: geom.maxH };
    const all = await loadUserComments();
    if (token !== threadRequest.value || !markEl.isConnected) return;
    store.notePopover = null;
    store.suggestionPopover = null;
    store.selectionAction = null;
    const c = all.find(
      (x) => x.id === commentId && x.folioId === store.activeFolioId,
    );
    if (!c) {
      // The mark exists but the body didn't sync. Show a placeholder
      // so the writer can resolve or delete it; the next addComment
      // round-trip will populate the body.
      store.userCommentPopover = {
        mode: "thread",
        visible: true,
        id: commentId,
        author: "You",
        text: "(comment body not yet synced)",
        quote: markEl.textContent ?? "",
        createdAt: Date.now(),
        ...place,
        from: null,
        to: null,
        resolved: false,
        replies: [],
        draft: threadDrafts[itemId] ?? "",
      };
      return;
    }
    store.userCommentPopover = {
      mode: "thread",
      visible: true,
      id: c.id,
      author: c.author,
      text: c.text,
      quote: c.anchor ?? markEl.textContent ?? "",
      createdAt: c.createdAt,
      ...place,
      from: null,
      to: null,
      resolved: c.resolved,
      replies: c.replies,
      draft: threadDrafts[itemId] ?? "",
    };
  },
);

/** Persist the captured comment locally and sync only to the same account. */
const persistNewComment = $(
  async (
    commentId: string,
    text: string,
    anchor: string,
    folioId: string,
    expectedAccount?: string | null,
  ) => {
    const account = auth.value.user?.id ?? null;
    if (expectedAccount !== undefined && expectedAccount !== account)
      return false;
    try {
      await upsertUserComment({
        id: commentId,
        folioId,
        text,
        author: "You",
        anchor,
        resolved: false,
        createdAt: Date.now(),
        updatedAt: Date.now(),
        replies: [],
      });
      // A local write already in progress belongs to its captured folio.
      // Never sync that write using a different account after an await.
      if ((auth.value.user?.id ?? null) !== account) return true;
      const client = clientSig.value;
      if (client && folioId && hasAuthenticatedConvexIdentity(auth.value)) {
        try {
          await client.mutation(api.userComments.addComment, {
            commentId,
            folioId,
            text,
            author: "You",
            anchor,
          });
        } catch (err) {
          reportCommentSyncError("add-comment", err);

      );
      if (!geometry) store.userCommentPopover = null;
      else if (moved(comment, geometry))
        store.userCommentPopover = { ...comment, ...geometry };
    }
    const suggestion = store.suggestionPopover;
    if (suggestion && suggestion.margin == null) {
      const geometry = place(
        markedRect("data-suggestion-id", suggestion.id),
        false,
      );
      if (!geometry) store.suggestionPopover = null;
      else if (moved(suggestion, geometry))
        store.suggestionPopover = { ...suggestion, ...geometry };
    }
  };
  const schedule = () => {
    if (!frame) frame = requestAnimationFrame(reposition);
  };
  scroller.addEventListener("scroll", schedule, { passive: true });
  window.addEventListener("resize", schedule);
  editor.on("update", schedule);
  const observer = new ResizeObserver(schedule);
  observer.observe(canvas);
  schedule();
  cleanup(() => {
    cancelAnimationFrame(frame);
    scroller.removeEventListener("scroll", schedule);
    window.removeEventListener("resize", schedule);
    editor.off("update", schedule);
    observer.disconnect();
  });
});

// Marginalia list deletion routes through the editor so the stored thread
// and its document mark cannot diverge.
// eslint-disable-next-line qwik/no-use-visible-task
useVisibleTask$(({ cleanup }) => {
  const onDeleteUserComment = (event: Event) => {
    const detail = (event as CustomEvent<{ commentId?: string }>).detail;
    if (!detail?.commentId) return;
    void deleteUserCommentLocal(detail.commentId);
  };
  const onUserCommentsChanged = () => {
    const open = store.userCommentPopover;
    if (!open || open.mode !== "thread") return;
    const openId = open.id;
    void loadUserComments().then((all) => {
      const latest = all.find((comment) => comment.id === openId);
      const current = store.userCommentPopover;
      if (!latest || !current || current.id !== openId) return;
      store.userCommentPopover = {
        ...current,
        author: latest.author,
        text: latest.text,
        quote: latest.anchor ?? current.quote,
        createdAt: latest.createdAt,
        resolved: latest.resolved,
        replies: latest.replies,
      };
    });
  };
  const onToggleUserCommentResolved = (event: Event) => {
    const detail = (
      event as CustomEvent<{ commentId?: string; resolved?: boolean }>
    ).detail;
    if (!detail?.commentId || typeof detail.resolved !== "boolean") return;
    const client = clientSig.value;
    if (!client || !hasAuthenticatedConvexIdentity(auth.value)) return;
    void client
      .mutation(api.userComments.setCommentResolved, {
        commentId: detail.commentId,
        resolved: detail.resolved,
      })
      .catch((err) => {
        reportCommentSyncError("resolve-comment-from-rail", err);
      });
  };
  window.addEventListener("twyne:delete-user-comment", onDeleteUserComment);
  window.addEventListener(
    "twyne:toggle-user-comment-resolved",
    onToggleUserCommentResolved,
  );
  window.addEventListener(
    "twyne:user-comments-changed",
    onUserCommentsChanged,
  );
  cleanup(() => {
    window.removeEventListener(
      "twyne:delete-user-comment",
      onDeleteUserComment,
    );
    window.removeEventListener(
      "twyne:toggle-user-comment-resolved",
      onToggleUserCommentResolved,
    );
    window.removeEventListener(
      "twyne:user-comments-changed",
      onUserCommentsChanged,
    );
  });

